// NanoHubUserCreateBulk is the builder for creating many NanoHubUser entities in bulk.
type NanoHubUserCreateBulk struct {
	config
	err      error
	builders []*NanoHubUserCreate
	conflict []sql.ConflictOption
}

// Save creates the NanoHubUser entities in the database.
func (nhucb *NanoHubUserCreateBulk) Save(ctx context.Context) ([]*NanoHubUser, error) {
	if nhucb.err != nil {
		return nil, nhucb.err
	}
	specs := make([]*sqlgraph.CreateSpec, len(nhucb.builders))
	nodes := make([]*NanoHubUser, len(nhucb.builders))
	mutators := make([]Mutator, len(nhucb.builders))
	for i := range nhucb.builders {
		func(i int, root context.Context) {
			builder := nhucb.builders[i]
			var mut Mutator = MutateFunc(func(ctx context.Context, m Mutation) (Value, error) {
				mutation, ok := m.(*NanoHubUserMutation)
				if !ok {
					return nil, fmt.Errorf("unexpected mutation type %T", m)
				}
				if err := builder.check(); err != nil {
					return nil, err
				}
				builder.mutation = mutation
				var err error
				nodes[i], specs[i] = builder.createSpec()
				if i < len(mutators)-1 {
					_, err = mutators[i+1].Mutate(root, nhucb.builders[i+1].mutation)
				} else {
					spec := &sqlgraph.BatchCreateSpec{Nodes: specs}
					spec.OnConflict = nhucb.conflict
					// Invoke the actual operation on the latest mutation in the chain.
					if err = sqlgraph.BatchCreate(ctx, nhucb.driver, spec); err != nil {
						if sqlgraph.IsConstraintError(err) {
							err = &ConstraintError{msg: err.Error(), wrap: err}
						}
					}
				}
				if err != nil {
					return nil, err
				}
				mutation.id = &nodes[i].ID
				if specs[i].ID.Value != nil {
					id := specs[i].ID.Value.(int64)
					nodes[i].ID = int(id)
				}
				mutation.done = true
				return nodes[i], nil
			})
			for i := len(builder.hooks) - 1; i >= 0; i-- {
				mut = builder.hooks[i](mut)
			}
			mutators[i] = mut
		}(i, ctx)
	}
	if len(mutators) > 0 {
		if _, err := mutators[0].Mutate(ctx, nhucb.builders[0].mutation); err != nil {
			return nil, err
		}
	}
	return nodes, nil
}

